  "POST /v1/orgs/audiences": {
    "service": "human-service",
    "method": "POST",
    "path": "/orgs/audiences",
    "schema": {
      "type": "object",
      "properties": {
        "name": {
          "type": "string",
          "minLength": 1
        },
        "brandId": {
          "type": "string",
          "format": "uuid"
        },
        "provider": {
          "type": "string",
          "enum": [
            "apollo",
            "apify",
            "crm"
          ],
          "description": "The provider this audience commits to. apollo/apify when persisting a candidate from /suggest; crm for a brand whose audience is its uploaded contact list (served by crm-service — no filters/apolloAudienceId, brand-scoped). Omit for a neutral audience."
        },
        "nlPrompt": {
          "type": "string",
          "minLength": 1
        },
        "filters": {
          "type": "object",
          "additionalProperties": {
            "nullable": true
          }
        },
        "apolloAudienceId": {
          "type": "string",
          "minLength": 1,
          "description": "Pointer to the faithful Apollo audience owned by apollo-service, when persisting an apollo candidate. Omit for a neutral / apify audience."
        },
        "crmUploadId": {
          "type": "string",
          "format": "uuid",
          "description": "Bind this audience to ONE imported CRM source (a crm-service upload id of the same brand). Every CRM serve made under this audience is then restricted to the people of that file, so several bound audiences can coexist for one brand and each is independently pausable + independently costed. Validated against the brand's uploads at creation (400 if it is not one of them). Omit to keep the whole-brand behaviour. Immutable afterwards."
        },
        "crmPeople": {
          "type": "object",
          "properties": {
            "signedUp": {
              "type": "boolean",
              "description": "true = only people who signed up to the brand's product (a signup on its auth provider); false = only people who did not."
            },
            "replied": {
              "type": "boolean",
              "description": "false = only people who NEVER wrote to the brand on any conversation channel (email, WhatsApp, LinkedIn, an answer to our outreach); true = only people who did."
            },
            "reachableBy": {
              "type": "string",
              "enum": [
                "phone",
                "email"
              ],
              "description": "Only people holding a phone / an email. A phone channel (WhatsApp, SMS) wants 'phone': a person served without one is burned for nothing."
            }
          },
          "additionalProperties": false,
          "description": "Bind this CRM audience to the brand's merged PEOPLE matching a filter (e.g. {signedUp: true, replied: false} = product signups who never answered) instead of to an imported file. Requires provider 'crm'; exclusive with crmUploadId. Every serve passes the filter to crm-service (same brand-wide no-re-serve forever); each served person carries its phone when crm-service holds one. Validated against crm-service's serve-stats at creation (its counts become the audience's Size / Remaining). Immutable afterwards."
        },
        "offerId": {
          "type": "string",
          "format": "uuid",
          "description": "The offer this audience belongs to — a brand-service offer id. Scopes the audience to one distinct thing the brand sells; name uniqueness becomes per (org, brand, offer), so two offers of the same brand may each own an audience with the same name. Stored as-is: human-service defines no offer semantics and does not resolve the id (same as brandId). Omit to keep the brand-wide behaviour. Immutable afterwards."
        },
        "apolloCount": {
          "type": "integer",
          "nullable": true,
          "minimum": 0,
          "description": "Optional count snapshot the caller already obtained from /orgs/people/search/dry-run (apollo). Stored as-is; refresh-count re-computes it server-side later. Accepts null (e.g. an apify-source candidate carries apolloCount: null)."
        },
        "apifyCount": {
          "type": "integer",
          "nullable": true,
          "minimum": 0,
          "description": "Optional apify count snapshot (see apolloCount). Accepts null (e.g. an apollo-source candidate carries apifyCount: null)."
        }
      },
      "required": [
        "name",
        "brandId"
      ]
    }
  },
