  "POST /v1/orgs/audiences/signal": {
    "service": "human-service",
    "method": "POST",
    "path": "/orgs/audiences/signal",
    "schema": {
      "type": "object",
      "properties": {
        "brandId": {
          "type": "string",
          "format": "uuid"
        },
        "offerId": {
          "type": "string",
          "format": "uuid",
          "description": "The brand-service offer this audience belongs to. Stored verbatim, like brandId. Omitted = brand-wide."
        },
        "name": {
          "type": "string",
          "minLength": 1,
          "maxLength": 200,
          "description": "Audience name (English), unique per (brand, offer). Omitted = apollo-service's label (competitor slugs + window)."
        },
        "nlPrompt": {
          "type": "string",
          "minLength": 1,
          "description": "Who among the engagers is worth writing to, in plain English (people, not only companies). Stored as the audience target: the pre-pay screen judges every engager teaser (name, title, headline, employer) against it before any email is paid for."
        },
        "status": {
          "type": "string",
          "enum": [
            "active",
            "paused"
          ],
          "description": "Initial status. Omitted = active."
        },
        "signal": {
          "type": "object",
          "properties": {
            "type": {
              "type": "string",
              "enum": [
                "linkedin_engagement"
              ]
            },
            "windowDays": {
              "type": "integer",
              "minimum": 1,
              "maximum": 365,
              "description": "Age of the competitor posts whose engagers are served, in days, counted back from each serve (rolling)."
            },
            "competitorPages": {
              "type": "array",
              "items": {
                "type": "string"
              },
              "description": "1-3 competitor LinkedIn company page URLs (https://www.linkedin.com/company/<slug>/). Validated by apollo-service, whose named 400 is relayed."
            }
          },
          "required": [
            "type",
            "windowDays",
            "competitorPages"
          ],
          "additionalProperties": false
        },
        "filters": {
          "type": "object",
          "additionalProperties": {
            "nullable": true
          },
          "description": "Apollo base filters. Must be empty: apollo-service refuses Apollo filters beside this signal with a named 400 (relayed), since its people are LinkedIn engagers, not an Apollo search. Omitted = {}."
        }
      },
      "required": [
        "brandId",
        "nlPrompt",
        "signal"
      ],
      "additionalProperties": false
    }
  },
