  "POST /v1/replies": {
    "service": "instantly-service",
    "method": "POST",
    "path": "/orgs/replies",
    "schema": {
      "type": "object",
      "properties": {
        "campaign_id": {
          "type": "string",
          "minLength": 1,
          "description": "Logical campaign id — the same key manual qualifications and opt-outs use. OPTIONAL: omit it and the thread is found from `email` alone. A thread is a campaign of this org in which the prospect wrote back. Exactly one → the reply goes into it. Several → 409 `ambiguous_thread` listing each candidate (`campaign_id` + `last_message_at`); call again naming one. None but we did email them → 409 `no_reply_to_thread`. Never emailed by this org → 404 `campaign_not_found`. When given, it is used as-is."
        },
        "email": {
          "type": "string",
          "format": "email",
          "description": "The prospect who replied. Matched case-insensitively. Enough on its own to find the thread when `campaign_id` is omitted."
        },
        "body_html": {
          "type": "string",
          "minLength": 1,
          "description": "The answer, HTML. Signed by this service with the sending account's persona — do NOT include a signature."
        },
        "sent_by": {
          "type": "string",
          "enum": [
            "human",
            "automation"
          ],
          "description": "Who asked for this answer to be sent. It decides ONE thing: whether the human-takeover gate applies. An `automation` reply is refused (409 `human_took_over`) once a person has answered the thread since the prospect last wrote; a `human` reply is never gated. Absent resolves to `automation` — the automated responder is the only caller today, so the gate is live without waiting on it, and a human surface declares `human` explicitly."
        }
      },
      "required": [
        "email",
        "body_html"
      ],
      "example": {
        "campaign_id": "c1a2b3c4-0000-0000-0000-000000000001",
        "email": "alice@media.com",
        "body_html": "<p>Great — how does Thursday 3pm look?</p>",
        "sent_by": "automation"
      }
    }
  },
