  "PUT /v1/brands/{id}/sales-rep": {
    "service": "brand-service",
    "method": "PUT",
    "path": "/orgs/brands/{brandId}/sales-rep",
    "schema": {
      "type": "object",
      "properties": {
        "salesRepEmail": {
          "type": "string",
          "nullable": true,
          "description": "The address to copy the rep on when a prospect replies. Required in practice: a write carrying a phone and no email is refused 400. Trimmed; otherwise stored exactly as typed. One bare address — the `Name <address>` form, several addresses, or anything that is not a plain address is refused.",
          "example": "kevin@acme.com"
        },
        "salesRepPhone": {
          "type": "string",
          "nullable": true,
          "description": "The number to ring, optional. Accepts any typed format (spaces, dashes, parentheses, dots) as long as it carries a country code — a leading `+` or the international `00` prefix — and is 8-15 digits; stored in strict E.164. Omitted or `null` means this rep is copied and never rung, and CLEARS a number that was there (the write replaces the whole rep). A national number with no country code is refused: no country is inferred, because a guess dials a different person.",
          "example": "+33770657585"
        },
        "salesRepFirstName": {
          "type": "string",
          "nullable": true,
          "description": "Optional. The rep's first name, used to introduce them by name when they are copied into a prospect's thread. OMITTED leaves the stored value untouched (unlike the phone, so a caller that does not send it never wipes it); `null` or a blank string clears it. Trimmed, single line, at most 60 characters.",
          "example": "Marie"
        },
        "salesRepRole": {
          "type": "string",
          "nullable": true,
          "description": "Optional. The rep's role / job title. OMITTED leaves the stored value untouched; `null` or a blank string clears it. Trimmed, single line, at most 100 characters.",
          "example": "Head of Partnerships"
        }
      }
    }
  },
  "PUT /v1/brands/{id}/sales-rep-phone": {
    "service": "brand-service",
    "method": "PUT",
    "path": "/orgs/brands/{brandId}/sales-rep-phone",
    "schema": {
      "type": "object",
      "properties": {
        "salesRepPhone": {
          "type": "string",
          "minLength": 1,
          "description": "The number to ring when a sales interest lands on this brand. Accepts any typed format (spaces, dashes, parentheses, dots) as long as it carries a country code — either a leading `+` or the international `00` prefix — and is 8-15 digits. Stored in strict E.164 (`+33770657585`). A national number with no country code is rejected 400: no country is inferred, because a guess dials a different person.",
          "example": "+33770657585"
        }
      },
      "required": [
        "salesRepPhone"
      ]
    }
  },
